son // Array of requirements stored as JSON\n  responsibilities Json // Array of responsibilities stored as JSON\n  benefits         String?   @db.Text\n  closingDate      DateTime\n  isPublished      Boolean   @default(false)\n  isActive         Boolean   @default(true)\n  publishedAt      DateTime?\n  applicationCount Int       @default(0)\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n  createdBy        String?\n  updatedBy        String?\n  creator          User?     @relation(\"JobCreator\", fields: [createdBy], references: [id])\n  updater          User?     @relation(\"JobUpdater\", fields: [updatedBy], references: [id])\n\n  // Relations\n  applications JobApplication[]\n\n  @@index([department])\n  @@index([isPublished, isActive, closingDate])\n  @@map(\"jobs\")\n}\n\nmodel JobApplication {\n  id            String            @id @default(cuid())\n  jobId         String\n  job           Job               @relation(fields: [jobId], references: [id], onDelete: Cascade)\n  name          String\n  email         String\n  phone         String\n  qualification String?\n  experience    Int?\n  coverLetter   String            @db.Text\n  cvUrl         String\n  status        ApplicationStatus @default(PENDING)\n  notes         String?           @db.Text\n  reviewedAt    DateTime?\n  reviewedBy    String?\n  createdAt     DateTime          @default(now())\n  updatedAt     DateTime          @updatedAt\n\n  /**\n   * Certificates, qualifications, IDs and other supporting documents.\n   */\n  documents JobApplicationDocument[]\n\n  @@index([jobId])\n  @@index([status])\n  @@index([email])\n  @@map(\"job_applications\")\n}\n\nmodel JobApplicationDocument {\n  id            String         @id @default(cuid())\n  applicationId String\n  application   JobApplication @relation(fields: [applicationId], references: [id], onDelete: Cascade)\n  /**\n   * Original filename as uploaded by the applicant.\n   */\n  fileName      String\n  /**\n   * Stored in the shared uploads root, served through /api/uploads/<file>.\n   */\n  fileUrl       String\n  fileSize      Int\n  fileType      String\n  /**\n   * Applicant-chosen document category, e.g. \"Certificate\".\n   */\n  label         String?\n  uploadedAt    DateTime       @default(now())\n\n  @@index([applicationId])\n  @@map(\"job_application_documents\")\n}\n\nenum ApplicationStatus {\n  PENDING\n  REVIEWING\n  SHORTLISTED\n  INTERVIEWED\n  ACCEPTED\n  REJECTED\n}\n\n// ============================================\n// CORRUPTION REPORTS\n// ============================================\n\nmodel CorruptionReport {\n  id           String  @id @default(cuid())\n  reportNumber String  @unique @default(uuid())\n  isAnonymous  Boolean @default(true)\n\n  // Optional contact info\n  name         String?\n  email        String?\n  phone        String?\n  organization String?\n\n  // Report details\n  corruptionType      String // 'bribery', 'embezzlement', 'fraud', etc.\n  incidentDescription String    @db.Text\n  location            String\n  province            String?\n  incidentDate        DateTime?\n  incidentTime        String?\n  peopleInvolved      String?   @db.Text\n  additionalInfo      String?   @db.Text\n  /**\n   * Optional voice note saved under public/uploads/reports\n   */\n  audioUrl            String?\n\n  // Status\n  status       ReportStatus   @default(NEW)\n  /**\n   * When status is CUSTOM, admin-defined label shown in UI and public track.\n   */\n  customStatus String?        @db.VarChar(200)\n  /**\n   * Admin list: hidden from default reports table until restored.\n   */\n  isArchived   Boolean        @default(false)\n  priority     ReportPriority @default(MEDIUM)\n  assignedTo   String?\n  notes        String?        @db.Text\n\n  // Relations\n  files   ReportFile[]\n  updates ReportUpdate[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([isArchived])\n  @@index([status])\n  @@index([corruptionType])\n  @@index([createdAt])\n  @@map(\"corruption_reports\")\n}\n\nmodel ReportFile {\n  id         String           @id @default(cuid())\n  reportId   String\n  report     CorruptionReport @relation(fields: [reportId], references: [id], onDelete: Cascade)\n  fileName   String\n  fileUrl    String\n  fileSize   Int\n  fileType   String\n  uploadedAt DateTime         @default(now())\n\n  @@index([reportId])\n  @@map(\"report_files\")\n}\n\nmodel ReportUpdate {\n  id           String           @id @default(cuid())\n  reportId     String\n  report       CorruptionReport @relation(fields: [reportId], references: [id], onDelete: Cascade)\n  status       ReportStatus\n  customStatus String?          @db.VarChar(200)\n  notes        String?          @db.Text\n  updatedBy    String?\n  createdAt    DateTime         @default(now())\n\n  @@index([reportId])\n  @@map(\"report_updates\")\n}\n\nenum ReportStatus {\n  NEW\n  ACKNOWLEDGED\n  UNDER_INVESTIGATION\n  REFERRED_TO_PROSECUTION\n  CLOSED\n  ARCHIVED\n  CUSTOM\n}\n\nenum ReportPriority {\n  LOW\n  MEDIUM\n  HIGH\n  URGENT\n}\n\n// ============================================\n// CONTACT SUBMISSIONS\n// ============================================\n\nenum ContactStatus {\n  NEW\n  IN_PROGRESS\n  RESPONDED\n  CLOSED\n}\n\nenum ContactCategory {\n  GENERAL\n  COMPLAINT\n  COMPLIMENT\n  INQUIRY\n  OTHER\n}\n\nmodel ContactSubmission {\n  id          String          @id @default(cuid())\n  name        String\n  email       String\n  phone       String?\n  subject     String\n  message     String          @db.Text\n  category    ContactCategory @default(GENERAL)\n  isAnonymous Boolean         @default(false)\n  status      ContactStatus   @default(NEW)\n  respondedAt DateTime?\n  response    String?         @db.Text\n  createdAt   DateTime        @default(now())\n  updatedAt   DateTime        @updatedAt\n\n  @@index([status])\n  @@index([createdAt])\n  @@index([category])\n  @@map(\"contact_submissions\")\n}\n\n// ============================================\n// MEDIA MANAGEMENT\n// ============================================\n\nmodel Media {\n  id           String   @id @default(cuid())\n  fileName     String\n  originalName String\n  fileUrl      String\n  thumbnailUrl String?\n  mimeType     String\n  fileSize     Int // Size in bytes\n  width        Int?\n  height       Int?\n  alt          String?\n  caption      String?\n  category     String? // 'image', 'document', 'video', etc.\n  folder       String? // For organization\n  uploadedBy   String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  @@index([category])\n  @@index([folder])\n  @@map(\"media\")\n}\n\n// ============================================\n// CONTACT INFORMATION\n// ============================================\n// Store contact details and addresses for offices\n// Examples: Head Office, Regional Offices, Report Centre\n// Includes: address, phone, email, office hours\n\nmodel ContactInfo {\n  id        String   @id @default(cuid())\n  type      String // 'head-office', 'regional-office', 'report-centre', etc.\n  name      String\n  address   String?  @db.Text\n  city      String?\n  province  String?\n  country   String   @default(\"Zimbabwe\")\n  phone     String?\n  email     String?\n  hours     String?  @db.Text\n  isActive  Boolean  @default(true)\n  order     Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([type])\n  @@map(\"contact_info\")\n}\n\n// ============================================\n// LEGISLATION CONTENT\n// ============================================\n\nmodel Legislation {\n  id          String   @id @default(cuid())\n  title       String\n  type        String // 'constitutional', 'act', 'regulation', 'international'\n  chapter     String? // e.g., \"Chapter 9:22\"\n  description String   @db.Text\n  content     String?  @db.Text\n  provisions  Json // Array of key provisions stored as JSON\n  downloadUrl String?\n  isPublished Boolean  @default(true)\n  order       Int      @default(0)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  @@index([type])\n  @@index([isPublished])\n  @@map(\"legislation\")\n}\n\n// ============================================\n// NEWSLETTER SUBSCRIPTIONS\n// ============================================\n\nmodel NewsletterSubscription {\n  id             String    @id @default(cuid())\n  email          String    @unique\n  isActive       Boolean   @default(true)\n  subscribedAt   DateTime  @default(now())\n  unsubscribedAt DateTime?\n  source         String? // Where they subscribed from\n\n  @@index([email])\n  @@index([isActive])\n  @@map(\"newsletter_subscriptions\")\n}\n\n// ============================================\n// ANALYTICS & TRACKING\n// ============================================\n\nmodel PageView {\n  id        String   @id @default(cuid())\n  pageType  String // 'home', 'about', 'news', 'rulings', etc.\n  pageId    String? // ID of specific content (news article, ruling, etc.)\n  url       String\n  ipAddress String?\n  userAgent String?\n  referrer  String?\n  viewedAt  DateTime @default(now())\n\n  @@index([pageType, pageId])\n  @@index([viewedAt])\n  @@map(\"page_views\")\n}\n\n// ============================================\n// MENU MANAGEMENT\n// ============================================\n\nmodel Menu {\n  id          String   @id @default(cuid())\n  name        String   @unique\n  location    String   @unique // 'header', 'footer', 'sidebar', etc.\n  description String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  items MenuItem[]\n\n  @@index([location])\n  @@map(\"menus\")\n}\n\nmodel MenuItem {\n  id        String  @id @default(cuid())\n  menuId    String\n  menu      Menu    @relation(fields: [menuId], references: [id], onDelete: Cascade)\n  label     String\n  type      String // 'custom', 'page', 'category', 'post', 'url'\n  url       String? // For custom links and URLs\n  target    String  @default(\"_self\") // '_self', '_blank'\n  icon      String? // Icon class or identifier\n  order     Int     @default(0)\n  isVisible Boolean @default(true)\n\n  // Hierarchical structure\n  parentId String?\n  parent   MenuItem?  @relation(\"MenuItemParent\", fields: [parentId], references: [id], onDelete: Cascade)\n  children MenuItem[] @relation(\"MenuItemParent\")\n\n  // For linking to content\n  pageId     String? // If type is 'page'\n  categoryId String? // If type is 'category'\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([menuId, order])\n  @@index([parentId])\n  @@map(\"menu_items\")\n}\n",
